<?php
require_once __DIR__.'/../includes/member.php';$user=require_login();if($user['role']==='admin')redirect('admin/dashboard.php');
expire_pickup_reservations((int)$user['id']);expire_unpaid_delivery_requests((int)$user['id']);activate_estimated_deliveries((int)$user['id']);
$items=rows('SELECT br.*,b.title,b.book_id,
 COALESCE((SELECT SUM(e.duration_days) FROM extensions e WHERE e.borrowing_id=br.id AND e.status="approved"),0) extension_days,
 (SELECT COUNT(*) FROM extensions e WHERE e.borrowing_id=br.id AND e.status="pending") extension_pending,
 (SELECT COUNT(*) FROM fines f WHERE f.borrowing_id=br.id AND f.status="unpaid") unpaid_fine_count
 FROM borrowings br JOIN books b ON b.id=br.book_id WHERE br.user_id=? ORDER BY br.created_at DESC',[$user['id']]);
member_start('Peminjaman Saya',$user,'peminjaman.php'); ?>
<section class="member-section"><div class="member-section-heading"><div><span class="member-kicker">DAFTAR PINJAMAN</span><h1>Peminjaman</h1></div></div><div class="member-table-wrap"><table><thead><tr><th>Buku</th><th>Mulai pinjam</th><th>Batas pengembalian / proses</th><th>Sisa waktu</th><th>Status</th><th>Aksi</th></tr></thead><tbody>
<?php foreach($items as $item):$status=$item['status'];$active=in_array($status,['active','overdue'],true);$pendingPickup=$status==='pickup_pending';$days=(int)ceil((strtotime($item['due_date'])-time())/86400);$remainingExtensionDays=53-(int)$item['extension_days'];$availableDurations=array_filter([3,7,14],static fn($duration)=>$duration<=$remainingExtensionDays);$canExtend=$status==='active'&&strtotime($item['due_date'])>=time()+2*86400&&(int)$item['renew_count']<6&&(int)$item['extension_pending']===0&&$availableDurations; ?>
<tr><td><b><?=e($item['title'])?></b><br><small><?=e($item['book_id'])?></small></td><td><?php if($pendingPickup):?>Menunggu konfirmasi admin<?php elseif($status==='in_transit'):?>Menunggu konfirmasi kurir<?php elseif($status==='awaiting_payment'):?>Menunggu pembayaran<?php elseif($active):?><?=date_id($item['borrowed_at'],true)?><?php else:?>—<?php endif;?></td><td><?php if($pendingPickup):?>Ambil sebelum <?=date_id($item['pickup_deadline'],true)?><?php elseif($active):?><?=date_id($item['due_date'],true)?><?php elseif($status==='in_transit'):?>Estimasi sampai <?=date_id($item['estimated_delivery'],true)?><?php elseif($status==='awaiting_payment'):?>Bayar sebelum <?=date_id($item['payment_deadline'],true)?><?php else:?>—<?php endif;?></td><td><?php if($active):?><?=$days>=0?'Dalam '.$days.' hari':'Terlambat '.abs($days).' hari'?><?php elseif($pendingPickup):?><?=max(0,(int)ceil((strtotime($item['pickup_deadline'])-time())/86400))?> hari untuk diambil<?php elseif($status==='in_transit'):?>Menunggu konfirmasi kurir<?php else:?>—<?php endif;?></td><td><?=member_borrowing_badge($status)?></td><td><?php if($active):?><div class="loan-actions"><?php if($canExtend):?><a class="renew-button" href="<?=e(url('member/perpanjangan.php?borrowing_id='.(int)$item['id']))?>">Ajukan perpanjangan</a><?php else:?><button class="renew-disabled" disabled>Ajukan perpanjangan</button><?php endif;?><?php if((int)$item['unpaid_fine_count']>0):?><a class="fine-button" href="<?=e(url('member/denda.php'))?>">Bayar denda</a><?php endif;?></div><?php elseif($status==='awaiting_payment'):?><a class="payment-resume-button" href="<?=e(url('member/pembayaran.php?id='.(int)$item['id']))?>">Lanjutkan pembayaran</a><?php elseif($status==='in_transit'):?><a href="<?=e(url('member/pelacakan.php?id='.(int)$item['id']))?>">Lihat pelacakan</a><?php else:?>—<?php endif;?></td></tr>
<?php endforeach;?><?php if(!$items):?><tr><td colspan="6">Belum ada peminjaman.</td></tr><?php endif;?></tbody></table></div><p class="muted">Jam layanan ambil langsung: Senin–Jumat 08.00–17.00, Sabtu 08.00–13.00. Minggu tutup. Peminjaman maksimal 7 hari.</p></section><?php member_end(); ?>


